import {spatialData} from './mumbai-growth-data.js?v=20261026-cities05';
export {spatialData};
export const policyViews={
 'city-mumbai-services':[['demand','Demand and supply'],['water','Water and waste'],['access','Who can use it?'],['outcomes','Homes and outcomes']],
 'city-mumbai-work-pollution':[['work','Work and security'],['air','Air pollution pathway'],['water','Wastewater pathway'],['interventions','Match the response']],
 'city-mumbai-management':[['community','Community decisions'],['citywide','Citywide decisions'],['partnership','Shared responsibilities'],['tradeoffs','Compare approaches']],
 'city-mumbai-policy':[['entitlement','Policy categories'],['relocation','Homes and livelihoods'],['reach','Target and reach'],['audit','Test the outcomes']],
 'city-mumbai-spatial-evidence':[['early','1975 epoch'],['late','2020 epoch'],['compare','Compare the maps'],['sample','Compare cells A and B']]
};
export const policyRequirements=Object.fromEntries(Object.entries(policyViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const policyAnimated=(k,v)=>k==='city-mumbai-services'?['demand','water','outcomes'].includes(v):k==='city-mumbai-work-pollution'?['air','water'].includes(v):k==='city-mumbai-management'?['community','citywide','partnership'].includes(v):k==='city-mumbai-policy'?v==='relocation':false;
export const sanitationData={period:'1996–2005',report:'September 2006',target:1000000,estimatedReach:400000,blocksApprox:330,seatsOver:5100};
export const spatialSamples=[{id:'A',row:30,col:30},{id:'B',row:15,col:40}].map(p=>({...p,values:spatialData.rows.map(e=>e.values[p.row][p.col])}));
export const budgetGap=(demand,supply)=>Math.max(0,demand-supply);
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const line=(d,c='#afc8d0',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,c='#f3b294',r=6)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#f4f0e6"/>`;
const box=(x,y,w,a,b='')=>`<rect x="${x}" y="${y}" width="${w}" height="${b?65:42}" rx="10" fill="#345468" stroke="#94b3c0"/>`+tx(x+10,y+25,a,12)+(b?tx(x+10,y+48,b,11):'');
const fig=(b,c)=>`<svg viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#edf2ee" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const link=(u,s)=>`<a href="${u}" target="_blank" rel="noopener">${s}</a>`;
const URLS={sanitation:'https://documents.worldbank.org/curated/en/620841468041130033/pdf/384560IN0Mumbai0slum01PUBLIC1.pdf',entitlement:'https://drpmumbai.maharashtra.gov.in/en/Citizen-Services/Entitlement',dharavi:'https://drpmumbai.maharashtra.gov.in/en/About-Us/Dharavi-an-Overview',project:'https://drpmumbai.maharashtra.gov.in/en/About-Us/About-the-project',air:'https://www.mpcb.gov.in/en/air-quality',ghsl:'https://data.jrc.ec.europa.eu/dataset/9f06f36f-4b11-47ec-abb0-4f8b7b1d72ea'};
const source=k=>`<p class="geo-caption">${k==='air'?link(URLS.air,'MPCB: monitoring and Mumbai source-apportionment report, July 2024')+'. Pathways are illustrative, not station measurements.':k==='entitlement'?link(URLS.entitlement,'Dharavi project authority: residential entitlement table')+' · checked 26 October 2026. Conditional policy, not completed delivery or individual eligibility advice.':k==='ghsl'?link(URLS.ghsl,'Pesaresi & Politis · European Commission JRC, GHS-BUILT-S R2023A V1.0')+' · '+link('https://creativecommons.org/licenses/by/4.0/','CC BY 4.0')+'. Adaptation: 60×60-cell window and shared colour bins. Epoch estimates, not photographs; 2020 uses temporal modelling.':k==='dharavi'?link(URLS.dharavi,'Dharavi project authority: enterprise and service history')+'. Not a survey of every household or independent redevelopment evaluation.':link(URLS.sanitation,'World Bank / WSP, sanitation report, September 2006')+' · '+link(URLS.project,'Dharavi project authority: redevelopment policy')+'. Historical evidence and policy intentions; not proof of current universal outcomes.'}</p>`;
const house=(x,y,h=60)=>`<path d="M${x} ${y}l30-20 30 20v${h}h-60Z" fill="#b8b5a3" stroke="#e4e0d2"/><rect x="${x+25}" y="${y+h-30}" width="14" height="30" fill="#244356"/>`;
function table(caption,headers,rows){return `<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data"><caption>${caption}</caption><thead><tr>${headers.map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;}
const colours=['#20394b','#7a9594','#a9c6b6','#e0c79e','#f48b72'];
const bin=n=>n===0?0:n<=100000?1:n<=300000?2:n<=600000?3:4;
function grid(epoch,x,y,size){const cells=spatialData.rows.find(e=>e.epoch===epoch).values,step=size/60;let b=`<rect x="${x}" y="${y}" width="${size}" height="${size}" fill="${colours[0]}" stroke="#abc5d0"/>`;for(let r=0;r<60;r++)for(let c=0;c<60;c++)if(cells[r][c]>0)b+=`<rect x="${x+c*step}" y="${y+r*step}" width="${step+.03}" height="${step+.03}" fill="${colours[bin(cells[r][c])]}"/>`;for(const p of spatialSamples)b+=`<rect x="${x+p.col*step}" y="${y+p.row*step}" width="${step}" height="${step}" fill="none" stroke="#fff" stroke-width="1.2"/>`+tx(x+(p.col+1)*step+2,y+(p.row+1)*step,p.id,12);return b;}
export function policyEvidence(kind='reach'){
 if(['early','late','compare','sample'].includes(kind)){
 let b=tx(20,25,'MUMBAI AREA · SATELLITE-DERIVED GRID',13),c='Same 60×60 km window; ESRI:54009 equal-area grid, one-kilometre cells. Estimated built-up surface, not population, tenure or a municipal boundary.';
 if(kind==='sample'){b+=tx(20,65,'Built-up surface in two source cells (m²)',13);for(const [i,p]of spatialSamples.entries()){const yy=110+i*100;b+=tx(20,yy,'Cell '+p.id+' · row '+p.row+', column '+p.col,13);for(let j=0;j<2;j++)b+=`<rect x="135" y="${yy+10+j*25}" width="${p.values[j]/1000}" height="16" fill="${j?'#efba9a':'#a5c5b6'}"/>`+tx(20,yy+23+j*25,String([1975,2020][j]),11)+tx(145+p.values[j]/1000,yy+23+j*25,p.values[j].toLocaleString('en-GB'),11);}b+=tx(20,328,'Bars start at zero · two selected cells, not city totals',11);return fig(b,c)+source('ghsl')+table('Selected source cells; zero-based array indices',['Cell','1975 m²','2020 m²'],spatialSamples.map(p=>[p.id,...p.values.map(v=>v.toLocaleString('en-GB'))]));}
 if(kind==='compare'){b+=tx(20,52,'1975 epoch',13)+tx(230,52,'2020 epoch',13)+grid(1975,20,65,190)+grid(2020,230,65,190);}
 else{const e=kind==='early'?1975:2020;b+=tx(20,49,e+' epoch · N approximately ↑',12)+grid(e,90,60,250);b+=line('M25 270v41h42','#e4ece8',2)+tx(22,260,'10 km',11);}
 const yy=kind==='compare'?283:329;for(let i=0;i<5;i++)b+=`<rect x="${20+i*82}" y="${yy-12}" width="11" height="11" fill="${colours[i]}" stroke="#d9e1db"/>`+tx(35+i*82,yy-2,['0','&gt;0–10','&gt;10–30','&gt;30–60','&gt;60'][i],10);if(kind==='compare')b+=tx(20,315,'Key: built-up surface as % of each 1 km² cell',11);else b+=tx(230,49,'Key: % of cell',11);
 return fig(b,c)+source('ghsl');
 }
 if(kind==='entitlement'){let b=tx(20,29,'RESIDENTIAL POLICY CATEGORIES',14)+box(20,70,400,'On or before 1 January 2000','350 sq ft · within Dharavi')+box(20,155,400,'After 1 January 2000, through 1 January 2011','300 sq ft · within MMR')+tx(20,254,'Other categories include hire-purchase provisions.',12)+tx(20,280,'Check documents, conditions, costs and delivery.',12)+tx(20,327,'Source table checked 26 October 2026',11);return fig(b,'Selected official residential categories. Policy entitlements are conditional, not proof of homes delivered; these rows do not cover every category.')+source('entitlement');}
 let b=tx(20,29,'HISTORICAL SANITATION PROGRAMME',14)+tx(20,55,'Residents · original target vs estimated reach',12);for(const[i,label,val]of [[0,'Original target',sanitationData.target],[1,'Estimated reach',sanitationData.estimatedReach]])b+=tx(20,101+i*96,label,13)+`<rect x="20" y="${113+i*96}" width="${val/1000000*370}" height="29" fill="${i?'#efba9a':'#a8c5b6'}"/>`+tx(20,163+i*96,val.toLocaleString('en-GB'),14);b+=tx(20,310,'1996–2005 programme · September 2006 report',11);return fig(b,'Original target about one million; estimated reach about 400,000. Denominator is the original programme target, not all Mumbai residents. Reach is not a measured disease reduction.')+source('sanitation')+table('Historical programme figures',['Measure','Residents'],[['Original target','1,000,000'],['Estimated reach','400,000']]);
}
export function policyScene(k,v,t=0){if(!policyViews[k])return '';if(!policyRequirements[k].includes(v))v=policyRequirements[k][0];t=policyAnimated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;if(k==='city-mumbai-spatial-evidence')return policyEvidence(v);if(k==='city-mumbai-policy'&&['entitlement','reach'].includes(v))return policyEvidence(v);let b='',c='',src='sanitation';
 if(k==='city-mumbai-services'){
 if(v==='demand'){const demand=Math.round(60+40*t),supply=Math.round(55+15*t);b=tx(20,30,'WHEN DEMAND GROWS FASTER THAN SUPPLY',13)+house(45,105)+house(300,105)+tx(20,215,'Demand: '+demand+' homes',14)+tx(20,255,'Available: '+supply+' homes',14)+`<rect x="20" y="225" width="${demand*3.8}" height="12" fill="#edb294"/><rect x="20" y="265" width="${supply*3.8}" height="12" fill="#aac5b3"/>`+tx(20,322,'Illustrative gap: '+budgetGap(demand,supply)+' homes',13);c='Invented equal-period scenario: demand rises from 60 to 100, supply from 55 to 70. Not Mumbai housing statistics, a forecast or equal household needs.';}
 else if(v==='water'){b=tx(20,30,'FOLLOW THE WATER AND WASTE CHAIN',13)+box(20,65,175,'Supply','Water connection')+box(245,65,175,'Use','Toilet / cleaning')+box(245,225,175,'Collect and treat','Safe disposal needed')+line('M195 95H245M332 130V225')+dot(195+50*t,95)+dot(332,130+95*t)+tx(20,210,'A working tap',14)+tx(20,235,'is one link.',14)+tx(20,325,'Safe access needs every link to function.',12);c='Conceptual supply → use → safe waste management. Tokens show sequence, not measured flows; clean water supply is distinct from wastewater treatment.';}
 else if(v==='access'){b=tx(20,30,'PROXIMITY IS NOT THE SAME AS ACCESS',13)+house(40,100)+box(230,90,185,'Nearby service','Clinic / water point')+line('M110 140H225','#b5d0c3',3)+box(20,245,125,'Connection?')+box(157,245,125,'Reliable?')+box(294,245,125,'Affordable?');c='A static access checklist. Compare connection, reliability, safety and affordability as well as distance; a schematic does not describe every household.';}
 else{b=tx(20,30,'FROM CONSTRUCTION TO USABLE HOUSING',13)+house(40,110,80)+box(220,85,200,'Safe occupancy','Costs / upkeep / access')+line('M110 150H215')+dot(110+105*t,150)+tx(20,270,t<.5?'Output: homes built':'Outcome: homes people can use',15)+tx(20,315,'Ask who benefits, who pays and who is excluded.',12);c='A conceptual evaluation sequence, not observed success. Building output must be followed by affordability, occupancy and quality-of-life evidence.';}
 }
 if(k==='city-mumbai-work-pollution'){
 src=v==='work'?'dharavi':v==='water'?'sanitation':'air';
 if(v==='work'){b=tx(20,30,'SEPARATE THE DIMENSIONS OF WORK',13)+box(20,75,400,'Employment status','Working / not working')+box(20,165,190,'Hours','Enough / insufficient')+box(230,165,190,'Protections','Formal / informal')+tx(20,290,'Paid work can still involve insecurity.',14)+tx(20,325,'These categories do not identify every worker’s situation.',11);c='Informal employment and under-employment are distinct dimensions. These are diagnostic categories, not a measured composition of Mumbai’s workforce.';}
 else if(v==='air'){b=tx(20,30,'SOURCE → AIR → EXPOSURE',14)+`<path d="M35 170h60v-40h25v100H35Z" fill="#9eb5b6"/><rect x="300" y="195" width="100" height="35" rx="12" fill="#d5b398"/>`+tx(20,260,'Industry / traffic / dust',12)+tx(270,260,'People and places',12)+line('M125 150Q210 80 320 150','#aac5b3',2);for(let i=0;i<5;i++){const p=(t+i/5)%1;b+=dot(125+195*p,150-65*Math.sin(Math.PI*p),'#e7c6a4',3+i%2);}b+=tx(20,320,'Exposure depends on location and conditions.',12);c='Illustrative airborne particle pathway, not Mumbai concentrations or a dispersion model. Different sources and weather affect exposure.';}
 else if(v==='water'){b=tx(20,30,'COLLECTION AND TREATMENT MATTER',14)+house(25,90)+box(175,70,235,'Wastewater system','Collect → treat → safe discharge')+line('M90 145H185V230H385','#9cc4cd',7)+`<path d="M20 260Q100 240 170 260T420 260V300H20Z" fill="#598392"/>`;for(let i=0;i<4;i++)b+=dot(185+200*((t+i/4)%1),230,'#b9d8d6',4);b+=tx(20,329,'Untreated discharge can harm receiving water.',12);c='Conceptual wastewater pathway, not a measured river or actual treatment-plant layout. Treatment performance needs separate evidence.';}
 else{b=tx(20,30,'MATCH THE ACTION TO THE PATHWAY',13)+box(20,75,400,'Airborne dust','Site controls / cleaner working practices')+box(20,165,400,'Untreated wastewater','Collection / treatment / safe discharge')+tx(20,280,'Then monitor comparable outcomes.',14)+tx(20,325,'One action does not remove every source.',12);c='A static intervention comparison. Air and water pollution require different measures; a policy announcement does not prove improvement.';}
 }
 if(k==='city-mumbai-management'){
 if(v==='community'){b=tx(20,30,'LOCAL DECISIONS AND ACCOUNTABILITY',13)+box(20,70,180,'Residents','Needs and feedback')+box(240,70,180,'Local management','Hours / cleaning')+line('M200 100H240M330 140L110 250M110 250V140')+box(20,245,180,'Check inclusion','Tenants / low incomes')+dot(200+40*t,100)+dot(330-220*t,140+110*t);c='Bottom-up participation can improve local fit; representation, funds and capacity can limit it. Timing and tokens are symbolic, not consultation counts.';}
 else if(v==='citywide'){b=tx(20,30,'COORDINATE A CITYWIDE NETWORK',14)+box(100,65,240,'Government / agencies','Finance and technical standards')+box(20,245,180,'Neighbourhood A')+box(240,245,180,'Neighbourhood B')+line('M180 140L110 240M260 140L330 240')+dot(180-70*t,140+100*t)+dot(260+70*t,140+100*t)+tx(20,325,'Large reach still needs local safeguards and voice.',12);c='Top-down coordination can support scale but does not guarantee equal benefits. This schematic is not a project boundary or delivery timetable.';}
 else if(v==='partnership'){b=tx(20,30,'COMPLEMENTARY RESPONSIBILITIES',13)+box(20,70,180,'Public sector','Networks / major repairs')+box(240,70,180,'Community','Operation / upkeep')+box(100,240,240,'Usable sanitation','Both roles need resources')+line('M110 140L185 235M330 140L255 235')+dot(110+75*t,140+95*t)+dot(330-75*t,140+95*t);c='Mumbai’s historical sanitation partnership combines public systems and local operation. A local committee does not replace trunk infrastructure or resolve every affordability problem.';}
 else{b=tx(20,30,'COMPARE THE SAME CRITERIA',14)+box(20,70,190,'Community-led','Local fit / local voice')+box(230,70,190,'Government-led','Scale / coordination')+box(20,175,190,'Possible constraints','Funds / representation')+box(230,175,190,'Possible constraints','Cost / displacement')+tx(20,297,'Judge reach, affordability and long-term upkeep.',12);c='Advantages and limitations are possible tendencies, not universal scores. Projects can combine approaches; an extended judgement needs evidence and trade-offs.';}
 }
 if(k==='city-mumbai-policy'){
 if(v==='relocation'){b=tx(20,30,'HOUSING AND LIVELIHOODS CONNECT',13)+house(30,95)+house(320,95)+box(130,235,180,'Existing work','Travel / suppliers')+line('M90 155L180 230M350 155L250 230')+dot(90+90*t,155+75*t)+dot(350-100*t,155+75*t)+tx(25,205,'Location A',12)+tx(315,205,'Location B',12)+tx(20,325,'Facilities, travel costs and networks all matter.',12);c='An illustrative relocation trade-off, not a map, measured commute or claim that everyone moves. Improved facilities can coexist with new livelihood costs.';src='entitlement';}
 else{b=tx(20,30,'AUDIT SOCIAL, ECONOMIC AND ENVIRONMENTAL RESULTS',11)+box(20,70,400,'Social','Safety / inclusion / affordable access')+box(20,155,400,'Economic','Work access / income / ongoing costs')+box(20,240,400,'Environmental','Waste treatment / exposure / resource use');c='A static outcomes framework. Targets, surveys, built units and causal health improvements measure different things; combine follow-up data and resident accounts.';}
 }
 return fig(b,c)+source(src);
}
